import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.HashSet;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }
        if (line == null) return;

        int n = Integer.parseInt(line.trim());

        HashSet<String> allSubstrings = new HashSet<>();
        HashSet<String> suffixes = new HashSet<>();
        HashSet<String> prefixes = new HashSet<>();

        String invalidString = null;

        for (int k = 0; k < n; k++) {
            line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            if (line == null) break;

            String s = line.trim();

            if (invalidString == null) {
                boolean found = false;

                // Verifica se s já é substring de alguma string anterior
                if (allSubstrings.contains(s)) {
                    found = true;
                } else {
                    // Verifica se s é combinação de sufixo(S_a) + prefixo(S_b)
                    int len = s.length();
                    for (int i = 1; i < len; i++) {
                        String pref = s.substring(0, i);
                        String suff = s.substring(i);
                        if (suffixes.contains(pref) && prefixes.contains(suff)) {
                            found = true;
                            break;
                        }
                    }
                }

                if (found) {
                    invalidString = s;
                } else {
                    int len = s.length();
                    // Adiciona todos os prefixos
                    for (int i = 1; i <= len; i++) {
                        prefixes.add(s.substring(0, i));
                    }
                    // Adiciona todos os sufixos
                    for (int i = 0; i < len; i++) {
                        suffixes.add(s.substring(i));
                    }
                    // Adiciona todas as substrings
                    for (int i = 0; i < len; i++) {
                        for (int j = i + 1; j <= len; j++) {
                            allSubstrings.add(s.substring(i, j));
                        }
                    }
                }
            }
        }

        if (invalidString != null) {
            System.out.println(invalidString);
        } else {
            System.out.println("ok");
        }
    }
}
